import { useEffect } from 'react'
import { ArrowRight, ArrowUpRight, Check, ChevronDown, Cloud, Code2, Database, Globe2, Layers3, MessageCircle, Menu, PanelTop, Search, ShieldCheck, ShoppingBag, Smartphone, Sparkles, Workflow } from 'lucide-react'

type ServicePageData = { slug: string; title: string; eyebrow: string; deck: string; intro: string; problems: string[]; deliver: string[]; capabilities: string[]; uses: string[]; stack: string[]; process: string[]; benefits: string[]; faq: [string, string][]; related: string[] }

export const servicePages: ServicePageData[] = [
  { slug: 'ai', title: 'AI & Machine Learning', eyebrow: 'Intelligence with a job to do', deck: 'Bring generative AI, machine learning and your business knowledge together to make useful tools for customers and teams.', intro: 'AI works best when it is connected to a real task, reliable information and a clear measure of usefulness. IAMTECHNI can help shape, integrate and build AI capabilities into the products and workflows your business already depends on.', problems: ['Knowledge is spread across documents, tools and teams.', 'People repeat the same research, drafting or data-entry work.', 'Existing software does not make business information easy to use.', 'A promising AI idea needs a safe, practical route into production.'], deliver: ['Generative AI experiences and LLM integrations', 'RAG applications, embeddings and vector search', 'Knowledge assistants, chatbots and AI agents', 'Document intelligence, extraction and classification', 'Machine learning and data-driven applications', 'AI APIs and workflow automation'], capabilities: ['Generative AI can draft, summarize, classify or transform content with human review.', 'RAG retrieves relevant material from approved sources before a model responds.', 'AI assistants give staff a conversational way to find internal knowledge.', 'Agents connect model reasoning with defined tools and business actions.', 'Document AI can extract structured fields from forms, invoices and files.', 'Machine learning can identify patterns and support forecasting when suitable data exists.'], uses: ['Search policies, product documentation or internal knowledge in natural language.', 'Classify enquiries and prepare suggested responses for a person to approve.', 'Extract fields from submitted documents and route exceptions for review.', 'Summarize long records so teams can get to the next decision sooner.', 'Connect AI to CRM, support or internal systems through controlled APIs.'], stack: ['Python', 'OpenAI and Gemini APIs', 'Embeddings and vector search', 'PostgreSQL', 'Node.js APIs'], process: ['Choose a narrow, valuable workflow and define what a useful result means.', 'Review the data, permissions and failure cases before selecting a model.', 'Prototype with representative content and human review points.', 'Integrate into the right application, then monitor quality and improve.'], benefits: ['Less repetitive knowledge work', 'Faster access to business information', 'More consistent first drafts and classification', 'AI features grounded in the tools and processes people already use'], faq: [['What is a RAG application?', 'Retrieval augmented generation searches a selected knowledge collection and provides relevant material to a language model so its response can be based on that context.'], ['Can AI use our private business documents?', 'It can be designed to retrieve from approved sources, with access controls and review requirements planned around the sensitivity of the information. Data handling depends on the chosen services and configuration.'], ['When should a person review AI output?', 'Review is useful when an answer affects money, legal or health matters, customer commitments, or any other high-impact decision. The workflow should make that boundary explicit.'], ['Do we need to train a custom model?', 'Often, no. A hosted model with good instructions, retrieval and integration may meet the need. Model training should be considered only when evaluation shows a clear reason.']], related: ['automation', 'software', 'cloud'] },
  { slug: 'web', title: 'Web Development', eyebrow: 'Useful experiences, built for the web', deck: 'Create a responsive business website or web application with a clear customer journey and a dependable technical foundation.', intro: 'A website often does several jobs at once: explain the business, earn trust, answer questions and help someone take action. We plan content, interaction, frontend and integrations together so the experience supports those jobs across devices.', problems: ['A dated website makes the offer hard to understand.', 'Mobile visitors struggle to browse or complete key actions.', 'Content updates depend on developer time.', 'Slow pages, poor structure or technical issues hold back discovery.'], deliver: ['Business and corporate websites', 'Landing pages and campaign experiences', 'React and Next.js applications', 'Custom frontend and backend APIs', 'CMS integration and content modelling', 'Third-party service and payment integrations'], capabilities: ['Responsive layouts designed for phones, tablets and desktop.', 'Frontend architecture that keeps interfaces consistent and maintainable.', 'Backend APIs to exchange data with applications and external services.', 'CMS workflows that help teams publish and revise content.', 'Technical SEO foundations, metadata, semantic HTML and crawlable structure.', 'Performance, accessibility, security and analytics considered from the start.'], uses: ['A corporate website that explains several services clearly.', 'A campaign landing page focused on one audience and action.', 'A customer portal or browser-based product built with React or Next.js.', 'A CMS-backed site connected to enquiry, CRM or analytics tools.'], stack: ['React', 'Next.js', 'TypeScript', 'Node.js', 'WordPress', 'REST APIs'], process: ['Map the audience, content and business actions the site needs to support.', 'Plan page hierarchy, content model, integrations and technical approach.', 'Design and develop responsive templates and reusable interface elements.', 'Test routes, devices, performance, accessibility and integrations before launch.'], benefits: ['A clearer path from first visit to enquiry or purchase', 'A site your team can maintain and extend', 'Better foundations for performance, search and accessibility', 'A digital front door connected to business tools'], faq: [['Should we use React or Next.js?', 'React is a library for building interfaces. Next.js adds a framework around React with routing and server-side options. The right choice depends on how the product needs to render, scale and integrate.'], ['Can you connect a CMS to a custom website?', 'Yes. A CMS can manage page content while a custom frontend controls how that content is presented. The content model should match how your team publishes.'], ['Does a new website guarantee search rankings?', 'No. A strong technical foundation helps search engines understand a site, but visibility also depends on competition, content quality, authority and ongoing work.'], ['How do you approach accessibility?', 'We consider semantic structure, keyboard navigation, focus visibility, colour contrast and clear interaction states during design and testing.']], related: ['ecommerce', 'marketing', 'software'] },
  { slug: 'ecommerce', title: 'eCommerce Development', eyebrow: 'Commerce from catalogue to checkout', deck: 'Build a coherent eCommerce ecosystem for products, customers, orders and the operations that support them.', intro: 'An online store is more than a product grid. It needs a dependable path from browsing to payment, plus clear processes for inventory, fulfilment, service and measurement. We can work with WooCommerce or shape a custom commerce experience around your requirements.', problems: ['Product information is difficult to maintain or browse.', 'Checkout creates avoidable friction on mobile.', 'Orders, stock and shipping live in disconnected systems.', 'Store performance, security or search visibility needs attention.'], deliver: ['WooCommerce stores and custom eCommerce', 'Product catalogues, categories and search', 'Shopping carts, checkout and payment integration', 'Customer accounts, order management and notifications', 'Inventory, shipping and fulfilment integrations', 'Coupons, analytics, SEO and performance improvements'], capabilities: ['Product data models that make catalogues easier to organise.', 'Cart and checkout journeys designed to reduce uncertainty.', 'Payment integrations selected for market and operational requirements.', 'Order status and customer account experiences.', 'Inventory and shipping connections to relevant business systems.', 'Store analytics and technical SEO foundations to guide improvement.'], uses: ['Launch a product catalogue with online ordering.', 'Connect an existing WooCommerce store to operational tools.', 'Build a custom storefront around distinctive product or account needs.', 'Improve mobile product discovery, checkout or post-purchase communication.'], stack: ['WooCommerce', 'WordPress', 'React', 'Next.js', 'Payment APIs', 'Analytics'], process: ['Understand products, customers, fulfilment and current tools.', 'Design catalogue structure and map the full purchase lifecycle.', 'Implement the storefront, payments and required integrations.', 'Test real purchase paths, edge cases, security and operational handoffs.'], benefits: ['A consistent experience from product discovery through order updates', 'Fewer manual steps between store and operations', 'Product and order information that is easier to manage', 'A foundation for measured conversion and performance improvements'], faq: [['WooCommerce or custom eCommerce: how do we choose?', 'WooCommerce can be a practical fit for many content-led stores and familiar catalogue needs. Custom commerce may suit specialised workflows, integrations or customer experiences. Scope and operating needs determine the trade-off.'], ['Can you connect inventory and shipping tools?', 'Yes, where the relevant systems provide suitable integrations or APIs. The project should map which system owns each piece of product, stock and fulfilment data.'], ['Can an existing store be improved without rebuilding?', 'Often. Performance, product navigation, checkout and technical SEO can be reviewed as separate improvement areas before deciding whether a rebuild is needed.'], ['Which payment providers can be added?', 'Payment options depend on your target markets, provider accounts and technical requirements. We can integrate an appropriate provider once those constraints are understood.']], related: ['web', 'marketing', 'software'] },
  { slug: 'mobile', title: 'Mobile App Development', eyebrow: 'Services that fit in people’s hands', deck: 'Plan and build Android, iOS or cross-platform applications that connect customers, teams and business systems.', intro: 'A mobile app earns its place when it makes a service more accessible or helps someone complete a task in context. Strategy, interface design, authentication, APIs, notifications and long-term maintenance all shape whether that experience remains useful.', problems: ['A mobile service needs more than a mobile-friendly website.', 'Field or frontline teams need task-specific tools away from a desk.', 'Customers need faster access to an account, service or transaction.', 'A concept needs a sensible platform and launch plan.'], deliver: ['App strategy and user experience design', 'Android and iOS application development', 'Cross-platform app architecture', 'Backend and API integration', 'Authentication, notifications and payments', 'Analytics, app deployment and maintenance'], capabilities: ['User flows and interface design focused on the key task.', 'Native or cross-platform implementation chosen for product needs.', 'Secure account flows and integration with existing APIs.', 'Push notifications used for relevant, timely updates.', 'Cloud-connected data and payment flows where required.', 'Release preparation, analytics and a plan for ongoing improvements.'], uses: ['Customer accounts, bookings, service requests or loyalty experiences.', 'Field service workflows, checklists and job updates.', 'Internal tools for distributed or mobile teams.', 'Companion applications for an existing digital service.'], stack: ['Android', 'iOS', 'Cross-platform frameworks', 'REST APIs', 'Cloud services', 'Push notification services'], process: ['Validate the user need, platform expectations and essential first release.', 'Design key flows and establish API and data requirements.', 'Build and test on representative devices and network conditions.', 'Prepare store submissions, analytics and a post-launch maintenance path.'], benefits: ['Convenient access to a service wherever users need it', 'Task flows designed around mobile context', 'A connected experience between app and business systems', 'A manageable plan for releases and updates'], faq: [['Native or cross-platform app: what is the difference?', 'Native apps are built for a specific platform. Cross-platform approaches share more code across iOS and Android. The choice depends on device requirements, experience, budget and future maintenance.'], ['Can an app use our existing backend?', 'Usually, if the backend exposes suitable APIs and authentication. The API may need changes to support mobile-specific use safely and reliably.'], ['Do you support app store launch?', 'Release planning can include build preparation, device checks, store assets and submission steps. Store accounts and final approval remain tied to the business owner.'], ['What happens after launch?', 'Mobile platforms and user needs evolve. Maintenance can include compatibility updates, bug fixes, security updates and improvements based on feedback.']], related: ['software', 'cloud', 'web'] },
  { slug: 'software', title: 'Custom Software', eyebrow: 'Software shaped around your operations', deck: 'Replace fragile workarounds with business systems, internal applications and integrations designed for the way your team works.', intro: 'When spreadsheets, repeated handoffs and disconnected products become the process, custom software can make the work clearer. The first step is understanding the rules, people and data involved before deciding what is worth building.', problems: ['Important work depends on manual copying between systems.', 'Off-the-shelf tools do not fit a core business process.', 'Teams lack a shared view of operational data.', 'Access, reporting or approvals are difficult to manage.'], deliver: ['Business management systems, CRM and ERP components', 'Internal applications and workflow systems', 'Dashboards, reporting and database applications', 'API platforms and third-party integrations', 'Authentication, role-based access and audit-aware flows', 'Automation, testing, deployment and maintenance'], capabilities: ['Requirements discovery and workflow mapping.', 'Application architecture and database design.', 'User interfaces designed around day-to-day tasks.', 'APIs to connect internal software and external services.', 'Authentication and role-based permissions.', 'Operational dashboards, reports and maintainable releases.'], uses: ['Track enquiries, jobs, inventory or service requests in one place.', 'Route approvals and exceptions with clear ownership.', 'Give managers a shared dashboard over operational data.', 'Connect CRM, finance, customer and internal tools through APIs.'], stack: ['React', 'Node.js', 'Python', 'PostgreSQL', 'REST APIs', 'Cloud platforms'], process: ['Map current work, edge cases, data ownership and user roles.', 'Agree a focused scope, architecture and delivery sequence.', 'Build in reviewable increments and validate with intended users.', 'Test access, reporting, integrations and operational readiness before release.'], benefits: ['Fewer repeated manual handoffs', 'Processes that are easier to see and improve', 'Access shaped around roles and responsibilities', 'A system that can evolve as requirements change'], faq: [['When is custom software a good investment?', 'It can make sense when a process is important, repeated and poorly served by available tools, and when the cost of workarounds is understood. A discovery phase can test that case before committing to a build.'], ['Can custom software integrate with our current tools?', 'Yes, when those tools offer APIs or other supported connection methods. Integration design should account for data ownership, permissions and what happens when a system is unavailable.'], ['Can we begin with a smaller first release?', 'Yes. A focused first release can validate the workflow with real users before adding secondary features. The architecture should still allow sensible growth.'], ['How are user roles handled?', 'Roles can determine which screens, records and actions a person can access. The rules should be defined from real responsibilities and tested explicitly.']], related: ['automation', 'ai', 'cloud'] },
  { slug: 'cloud', title: 'Cloud & DevOps', eyebrow: 'A dependable path from code to production', deck: 'Make deployment repeatable, infrastructure understandable and production systems easier to observe and improve.', intro: 'Cloud and DevOps practices connect software delivery to the infrastructure it runs on. The right setup depends on workload, team skills, security needs and operating costs. We help businesses make deliberate choices rather than add complexity by default.', problems: ['Deployments depend on manual steps or one person’s knowledge.', 'Development and production behave differently.', 'Infrastructure is difficult to scale, secure or monitor.', 'Recovery and backup expectations are unclear.'], deliver: ['AWS and Azure cloud architecture', 'Docker containers and Kubernetes where useful', 'CI/CD with Jenkins or GitHub Actions', 'Infrastructure configuration and deployment', 'Monitoring, logging and security practices', 'Backup, recovery planning and scaling options'], capabilities: ['AWS and Azure offer managed infrastructure services for different requirements.', 'Docker packages applications consistently across environments.', 'Kubernetes orchestrates containers and can help when deployment complexity justifies it.', 'CI/CD automates build, checks and release steps to make delivery repeatable.', 'Monitoring and logging help teams understand system health and investigate issues.', 'Backups and recovery plans define how data and services can be restored.'], uses: ['Move a web application to a cloud environment.', 'Create repeatable build, test and deployment pipelines.', 'Containerise a service so environments behave consistently.', 'Improve observability, access management and recovery readiness.'], stack: ['AWS', 'Azure', 'Docker', 'Kubernetes', 'Jenkins', 'GitHub Actions'], process: ['Review workloads, constraints, current hosting and operational ownership.', 'Design the smallest architecture that meets availability and security needs.', 'Automate environments and delivery steps incrementally.', 'Monitor operation, document recovery and revisit capacity as usage changes.'], benefits: ['More predictable releases', 'Clearer infrastructure ownership and configuration', 'Earlier visibility into errors and performance', 'A practical route to scaling and recovery'], faq: [['AWS or Azure: which should we use?', 'Both provide broad cloud services. Existing skills, integrations, compliance needs, workloads and commercial arrangements help determine the best fit.'], ['When is Kubernetes useful?', 'It can help operate multiple containerised services with orchestration needs. For a small application, a simpler managed container or platform service may be easier to run.'], ['What does CI/CD mean?', 'Continuous integration and delivery automate steps such as building, checking and releasing software. Pipelines make those steps repeatable, with approvals added where appropriate.'], ['Does cloud automatically make a system secure?', 'No. Identity, configuration, application code, network boundaries, updates, backups and monitoring all contribute to security and need ongoing attention.']], related: ['software', 'web', 'automation'] },
  { slug: 'marketing', title: 'Digital Marketing', eyebrow: 'Make digital work easier to find', deck: 'Bring website quality, search visibility, useful content and conversion measurement into one practical growth effort.', intro: 'Marketing performs best when the website experience supports the promise that brought a visitor there. We connect technical SEO, local visibility, content, analytics and conversion improvements so activity can be measured against real business goals.', problems: ['Potential customers have difficulty finding the business online.', 'A website receives visits but does not guide people to the next step.', 'Local listings and site information are inconsistent.', 'Marketing activity is difficult to measure or prioritise.'], deliver: ['Technical, on-page and local SEO', 'Content strategy and search-focused information architecture', 'Social media planning and brand visibility support', 'Google Business Profile setup and optimisation', 'Analytics, conversion optimisation and lead generation', 'eCommerce marketing and product discovery'], capabilities: ['Technical SEO addresses crawlability, site structure, metadata and performance.', 'Local SEO helps location-aware searches find accurate business information.', 'Content strategy answers the questions customers use to evaluate options.', 'Analytics connects visits and actions to agreed measurement goals.', 'Conversion optimisation improves clarity, form flow and next-step guidance.', 'eCommerce marketing connects product discovery with store experience.'], uses: ['Strengthen local service discovery and business listings.', 'Build a content plan around customer questions and service pages.', 'Understand which channels lead to useful enquiries.', 'Improve product landing pages and store discovery.'], stack: ['Search Console', 'Analytics platforms', 'Google Business Profile', 'CMS tools', 'SEO tooling', 'CRM integrations'], process: ['Clarify audiences, services, geography and business objectives.', 'Review site health, current search presence and measurement setup.', 'Prioritise technical fixes, useful content and conversion opportunities.', 'Measure results and refine the plan using observed behaviour.'], benefits: ['More coherent information for search engines and visitors', 'Clearer insight into enquiry and purchase journeys', 'A website experience aligned with campaign promises', 'Marketing work prioritised around business objectives'], faq: [['How are website quality, SEO and conversion connected?', 'Useful content and technical clarity help people and search engines understand a site. A fast, accessible experience with clear next steps can help visitors act once they arrive. Each contributes differently and needs measurement.'], ['Can you guarantee first-page rankings?', 'No. Search results depend on competition, location, content, authority and many changing factors. SEO work improves site foundations and relevance, but rankings cannot be guaranteed.'], ['What is local SEO?', 'Local SEO helps a business appear accurately for searches with geographic intent. It can include consistent business information, location-focused pages and a well-managed Google Business Profile.'], ['How do you measure lead generation?', 'Measurement starts by defining meaningful actions, such as completed enquiry forms or calls, then configuring analytics and checking that the recorded events reflect real outcomes.']], related: ['web', 'ecommerce', 'automation'] },
  { slug: 'automation', title: 'Business Automation', eyebrow: 'Fewer repeated steps, clearer handoffs', deck: 'Connect the tools and rules behind routine work with dependable workflows, integrations and AI where it fits.', intro: 'Automation is useful when a process is understood, repeated and currently consumes avoidable attention. We map the handoffs first, then connect APIs, business rules, notifications and data processing with sensible review and exception paths.', problems: ['People re-enter the same information in multiple systems.', 'Requests wait in inboxes without clear ownership.', 'Reports require repetitive manual collection and formatting.', 'Documents need sorting, extracting or routing before work can continue.'], deliver: ['Business workflows and custom process automation', 'CRM, email and API automation', 'Data processing, reporting and notifications', 'Document processing and extraction', 'AI-assisted workflow steps with human review', 'Custom integrations and exception handling'], capabilities: ['Workflow mapping makes inputs, owners, rules and exceptions visible.', 'API automation transfers information between supported systems.', 'CRM automation can route, update and notify based on agreed rules.', 'Email automation can send timely messages tied to real events.', 'Document processing can classify files and extract fields for review.', 'Reporting automation can prepare recurring views from connected sources.'], uses: ['Send an enquiry to the right CRM owner and notify the team.', 'Extract document details, validate key fields and route exceptions.', 'Prepare recurring operational reports from business data.', 'Create follow-up reminders when a customer or task reaches a defined stage.'], stack: ['REST APIs', 'CRM platforms', 'Email services', 'Python', 'Workflow tools', 'AI APIs'], process: ['Document the current process, systems, exceptions and ownership.', 'Choose one workflow and define the trigger, rules and successful outcome.', 'Build connections with logging, access controls and human review where needed.', 'Test normal and exception paths, then monitor and adjust the workflow.'], benefits: ['Less manual copying between systems', 'More consistent routing and follow-up', 'Faster visibility into exceptions', 'Time returned to work that needs human judgement'], faq: [['What should we automate first?', 'Start with a repeated process that has stable rules, visible effort and manageable exceptions. A small workflow is easier to evaluate than automating an unclear end-to-end process.'], ['Can automation connect our existing tools?', 'Often, through supported APIs or integrations. The systems involved and their access limits determine what is possible and how failures should be handled.'], ['Where does AI fit in automation?', 'AI can help interpret unstructured text or documents, but its output may be uncertain. Use validation, confidence checks or human approval when a mistake matters.'], ['What happens if an automated step fails?', 'A sound workflow should record the issue, notify an owner and provide a route to retry or handle the exception without silently losing work.']], related: ['ai', 'software', 'cloud'] },
]

const icons = [Sparkles, PanelTop, ShoppingBag, Smartphone, Code2, Cloud, Search, Workflow]
const labels: Record<string, string> = { ai: 'AI & Machine Learning', web: 'Web Development', ecommerce: 'eCommerce', mobile: 'Mobile Apps', software: 'Custom Software', cloud: 'Cloud & DevOps', marketing: 'Digital Marketing', automation: 'Automation' }
const contentLinks = (text: string) => text.split(/(AI|automation|web|eCommerce|mobile|custom software|cloud|marketing)/gi).map((part, index) => { const slug = Object.entries(labels).find(([, label]) => label.toLowerCase() === part.toLowerCase())?.[0]; return slug ? <a key={index} href={`/services/${slug}`}>{part}</a> : part })

export default function ServicePages() {
  const rawSlug = decodeURIComponent(window.location.pathname.split('/').filter(Boolean).pop() || '')
  const slug = ({'ai-machine-learning':'ai','web-development':'web','mobile-app-development':'mobile','custom-software':'software','cloud-devops':'cloud','digital-marketing':'marketing'} as Record<string,string>)[rawSlug] || rawSlug
  const isOverview = slug === 'services'
  const isContact = slug === 'contact'
  const isPortfolio = slug === 'portfolio'
  const data = servicePages.find(page => page.slug === slug)
  const pageTitle = isContact ? 'Contact IAMTECHNI' : isPortfolio ? 'Portfolio' : isOverview ? 'Technology services for the work ahead' : data?.title || 'About IAMTECHNI'
  useEffect(() => { document.title = `${pageTitle} | IAMTECHNI`; const meta = document.querySelector('meta[name="description"]'); meta?.setAttribute('content', isContact ? 'Contact IAMTECHNI about web, AI, eCommerce, mobile, software, cloud, marketing or automation work.' : isOverview ? 'Explore web development, AI, eCommerce, mobile apps, custom software, cloud, digital marketing and automation services from IAMTECHNI.' : data?.deck || 'Learn about IAMTECHNI, our technology capabilities and practical approach to digital work.') }, [pageTitle, isOverview, isContact, data])
  if (isContact) return <ContactPage />
  if (isPortfolio) return <PortfolioPage />
  if (isOverview) return <ServicesPage />
  if (!data) return <AboutPage />
  const idx = servicePages.findIndex(page => page.slug === slug)
  const Icon = icons[idx]
  return <main className={`detail-page service-detail-page detail-${slug}`}><DetailHeader /><section className="detail-hero"><span className="detail-eyebrow"><Icon size={15} /> {data.eyebrow}</span><h1>{data.title}</h1><p>{data.deck}</p><div className="detail-hero-actions"><a className="button button-primary" href="/#contact">Discuss your project <ArrowUpRight size={16} /></a><a className="button-text" href="#overview">Explore the approach <ArrowRight size={15} /></a></div><div className="detail-hero-visual"><div className="detail-visual-orbit orbit-one"/><div className="detail-visual-orbit orbit-two"/><div className="detail-visual-core"><Icon size={46}/><b>{data.title}</b><span>Thoughtfully connected</span></div><span className="detail-node node-one"><Database size={17}/>{data.stack[0]}</span><span className="detail-node node-two"><Layers3 size={17}/>{data.stack[1]}</span><span className="detail-node node-three"><ShieldCheck size={17}/>{data.stack[2]}</span></div></section>
    <section className="detail-body" id="overview"><div className="detail-intro"><span>THE OPPORTUNITY</span><h2>{data.title} should make<br /><em>business easier.</em></h2><p>{data.intro}</p><a className="inline-link" href="/#contact">Talk through the challenge <ArrowUpRight size={15}/></a></div><div className="detail-split"><div><span className="detail-kicker">PROBLEMS WE SOLVE</span><h2>Start with what<br />slows work down.</h2></div><ul className="check-list">{data.problems.map(item=><li key={item}><Check size={17}/>{item}</li>)}</ul></div><section className="detail-capabilities"><div className="detail-section-heading"><span className="detail-kicker">WHAT WE PROVIDE</span><h2>Practical capabilities,<br /><em>connected to your goals.</em></h2></div><div className="capability-columns">{[data.deliver.slice(0,3),data.deliver.slice(3)].map((group,i)=><ul key={i}>{group.map(item=><li key={item}><ArrowUpRight size={16}/>{item}</li>)}</ul>)}</div><div className="capability-explain">{data.capabilities.map((item,i)=><article key={item}><span>0{i+1}</span><p>{item}</p></article>)}</div></section><section className="detail-use"><div><span className="detail-kicker">WHERE IT CAN HELP</span><h2>Real work.<br />Useful outcomes.</h2><p>These are common patterns, not promises about a particular business. The best scope depends on your process, systems and customers.</p></div><ul>{data.uses.map(item=><li key={item}><ArrowRight size={16}/>{item}</li>)}</ul></section><section className="detail-tech"><div><span className="detail-kicker">TECHNOLOGY ECOSYSTEM</span><h2>Tools serve<br />the solution.</h2><p>Technology choices follow the requirements, integrations, team and operating model. The stack is a starting point for a conversation, not a fixed recipe.</p></div><div className="tech-category"><span>TECHNOLOGIES</span>{data.stack.map(item=><b key={item}>{item}</b>)}</div></section><section className="detail-process"><div className="detail-section-heading"><span className="detail-kicker">A THOUGHTFUL DELIVERY APPROACH</span><h2>Make progress<br />in clear steps.</h2></div><div className="detail-process-list">{data.process.map((item,i)=><article key={item}><span>0{i+1}</span><p>{item}</p></article>)}</div></section><section className="detail-benefits"><div><span className="detail-kicker">WHAT GOOD CAN ENABLE</span><h2>Built around<br />better work.</h2></div><ul>{data.benefits.map(item=><li key={item}><Check size={17}/>{item}</li>)}</ul></section><section className="detail-faq"><span className="detail-kicker">QUESTIONS, ANSWERED</span><h2>Before you get started.</h2><div className="faq-list">{data.faq.map(([q,a])=><details key={q}><summary>{q}<ChevronDown size={18}/></summary><p>{a}</p></details>)}</div></section><nav className="related-services" aria-label="Related services"><span>RELATED CAPABILITIES</span>{data.related.map(rel=><a key={rel} href={`/services/${rel}`}>{labels[rel]} <ArrowUpRight size={15}/></a>)}</nav><section className="detail-cta"><span className="detail-kicker">A USEFUL NEXT STEP</span><h2>Let's work out<br /><em>what you need.</em></h2><p>Share the goal, the challenge or the process you want to improve. A first conversation can help identify a sensible next step.</p><a className="button button-light" href="/#contact">Start a conversation <ArrowUpRight size={16}/></a><a className="detail-cta-secondary" href="/services">Explore all services <ArrowRight size={15}/></a></section></section><DetailFooter /></main>
}

function DetailHeader(){return <header className="detail-header" id="top"><a className="detail-brand" href="/" aria-label="IAMTECHNI home"><img src="/iamtechni-logo.png" alt="IAMTECHNI"/></a><nav className="detail-nav" aria-label="Main navigation"><a href="/">Home</a><a href="/about">About</a><details className="service-mega"><summary>Services<ChevronDown size={14}/></summary><div className="mega-panel"><div><span>BUILD</span>{['web','ecommerce','mobile','software'].map(slug=><a key={slug} href={`/services/${{web:'web-development',ecommerce:'ecommerce',mobile:'mobile-app-development',software:'custom-software'}[slug]}`}><i>{slug==='web'?<PanelTop size={17}/>:slug==='ecommerce'?<ShoppingBag size={17}/>:slug==='mobile'?<Smartphone size={17}/>:<Code2 size={17}/>}</i><span><b>{labels[slug]}</b><small>{servicePages.find(x=>x.slug===slug)?.deck}</small></span></a>)}</div><div><span>INTELLIGENCE</span>{['ai','automation'].map(slug=><a key={slug} href={`/services/${slug==='ai'?'ai-machine-learning':'automation'}`}><i>{slug==='ai'?<Sparkles size={17}/>:<Workflow size={17}/>}</i><span><b>{labels[slug]}</b><small>{servicePages.find(x=>x.slug===slug)?.deck}</small></span></a>)}</div><div><span>SCALE</span>{['cloud','marketing'].map(slug=><a key={slug} href={`/services/${slug==='cloud'?'cloud-devops':'digital-marketing'}`}><i>{slug==='cloud'?<Cloud size={17}/>:<Search size={17}/>}</i><span><b>{labels[slug]}</b><small>{servicePages.find(x=>x.slug===slug)?.deck}</small></span></a>)}</div></div></details><a href="/portfolio">Portfolio</a><a href="/contact">Contact</a></nav><a className="detail-nav-cta desktop-contact" href="/contact">Let’s talk <ArrowUpRight size={15}/></a><details className="mobile-service-menu"><summary aria-label="Toggle navigation"><Menu size={20}/><span className="sr-only">Toggle navigation</span></summary><div><a href="/">Home</a><a href="/about">About</a><details><summary>Services <ChevronDown size={14}/></summary><div>{[['AI & Machine Learning','ai-machine-learning'],['Web Development','web-development'],['eCommerce Development','ecommerce'],['Mobile App Development','mobile-app-development'],['Custom Software','custom-software'],['Cloud & DevOps','cloud-devops'],['Digital Marketing','digital-marketing'],['Business Automation','automation']].map(([name,path])=><a key={path} href={`/services/${path}`}>{name}</a>)}</div></details><a href="/portfolio">Portfolio</a><a href="/contact">Contact</a><div className="mobile-menu-contact"><a href="mailto:iamtechni.hr@outlook.com">iamtechni.hr@outlook.com</a><a href="tel:+917418120053">+91 74181 20053</a></div></div></details></header>}
function DetailFooter(){return <footer className="site-footer detail-site-footer"><div className="footer-main page-shell"><div className="footer-brand"><a className="brand brand-footer" href="/" aria-label="IAMTECHNI home"><span className="brand-crop"><img src="/iamtechni-logo.png" alt="IAMTECHNI"/></span></a><p>Practical technology for businesses ready to build what’s next.</p></div><div className="footer-column"><span>EXPLORE</span><a href="/services">Services</a><a href="/about">About IAMTECHNI</a><a href="/portfolio">Selected work</a><a href="/contact">Let’s talk</a></div><div className="footer-column"><span>CAPABILITIES</span><a href="/services/web-development">Web development</a><a href="/services/ai-machine-learning">AI &amp; machine learning</a><a href="/services/cloud-devops">Cloud &amp; DevOps</a><a href="/services/custom-software">Custom software</a></div><div className="footer-contact"><span>GET IN TOUCH</span><p>Pondicherry, India<br/>Working across Tamil Nadu</p><a href="mailto:iamtechni.hr@outlook.com">iamtechni.hr@outlook.com</a><a href="tel:+917418120053">+91 74181 20053</a><a href="/contact">Let’s talk <ArrowUpRight size={14}/></a></div></div><div className="footer-bottom page-shell"><span>© 2026 IAMTECHNI. All rights reserved.</span><a href="#top">Back to top <ArrowUpRight size={13}/></a></div></footer>}function ServicesPage(){return <main className="detail-page detail-services"><DetailHeader/><section className="services-editorial-hero"><div className="services-hero-copy"><span className="detail-eyebrow">WHAT WE BUILD</span><h1>Technology Solutions Built Around Your Business</h1><p>IAMTECHNI brings together AI, web, mobile, software, cloud and digital growth capabilities to solve practical business challenges. Start with an outcome; shape the right combination of technology around it.</p><a className="button button-primary" href="/contact">Explore a project <ArrowUpRight size={16}/></a></div><div className="services-hero-art" aria-label="Connected technology capabilities"><div className="services-art-ring ring-a"/><div className="services-art-ring ring-b"/><div className="services-art-core"><Layers3 size={35}/><b>One connected<br/>technology partner</b></div><span className="services-art-chip chip-ai">AI</span><span className="services-art-chip chip-web">WEB</span><span className="services-art-chip chip-cloud">CLOUD</span><span className="services-art-chip chip-grow">GROWTH</span></div></section><section className="service-explorer"><header><div><span className="detail-kicker">EXPLORE CAPABILITIES</span><h2>Different disciplines.<br/><em>One connected view.</em></h2></div><p>Each service can stand alone or support a larger solution. Explore the work, useful capabilities and technology involved.</p></header><div className="explorer-featured"><a className="explorer-ai" href="/services/ai-machine-learning"><span className="explorer-label">INTELLIGENCE</span><div className="ai-graph-art"><i/><i/><i/><i/><i/><i/><b><Sparkles size={31}/></b></div><div><h3>AI &amp; Machine Learning</h3><p>Ground generative AI, assistants, RAG and machine learning in real business information and workflows.</p><span className="explorer-tech">OpenAI · Gemini · Python · Vector search</span></div><ArrowUpRight size={19}/></a><a className="explorer-web" href="/services/web-development"><div className="browser-mini"><div><i/><i/><i/><span>business.site</span></div><section><b>Clear digital<br/>experiences.</b><small>WEB · CMS · API</small></section></div><div><span className="explorer-label">DIGITAL PRODUCTS</span><h3>Web Development</h3><p>Corporate websites, responsive applications, APIs, CMS and the foundations for search and performance.</p><span className="explorer-tech">React · Next.js · TypeScript</span></div></a></div><div className="explorer-split"><a className="explorer-commerce" href="/services/ecommerce"><span className="explorer-label">COMMERCE</span><div className="commerce-art"><div className="product-shape shape-one"/><div className="product-shape shape-two"/><div className="cart-bubble"><ShoppingBag size={20}/><b>Cart</b><span>Checkout</span></div></div><h3>eCommerce Development</h3><p>Connect catalogue, product discovery, payments, orders and fulfilment in a store experience made for customers and operators.</p><span className="explorer-tech">WooCommerce · Payments · Inventory</span><ArrowUpRight size={19}/></a><a className="explorer-mobile" href="/services/mobile-app-development"><span className="explorer-label">MOBILE EXPERIENCES</span><div className="phone-duo"><div><i/><b>Today,<br/>in focus.</b><span/><span/></div><div><i/><b>Quick<br/>actions.</b><span/><span/></div></div><h3>Mobile App Development</h3><p>Android, iOS and cross-platform apps with considered UI/UX and connected services.</p><span className="explorer-tech">iOS · Android · APIs</span><ArrowUpRight size={19}/></a></div><div className="explorer-trio"><a className="explorer-cloud" href="/services/cloud-devops"><span className="explorer-label">INFRASTRUCTURE</span><div className="cloud-flow"><span>CODE</span><i/><span>BUILD</span><i/><span>SHIP</span></div><h3>Cloud &amp; DevOps</h3><p>Cloud architecture, repeatable releases, monitoring and recovery planning.</p><span className="explorer-tech">AWS · Azure · Docker · CI/CD</span><ArrowUpRight size={18}/></a><a className="explorer-marketing" href="/services/digital-marketing"><span className="explorer-label">DISCOVERY &amp; GROWTH</span><div className="growth-chart"><i/><i/><i/><i/><i/><b>Find · Understand · Improve</b></div><h3>Digital Marketing</h3><p>SEO, local discovery, content and conversion measurement tied to the website experience.</p><span className="explorer-tech">SEO · Analytics · Content</span><ArrowUpRight size={18}/></a><a className="explorer-automation" href="/services/automation"><span className="explorer-label">CONNECTED WORK</span><div className="automation-flow"><b>TRIGGER</b><i/><b>RULE</b><i/><b>ACTION</b></div><h3>Business Automation</h3><p>Move routine information between tools with clear rules and exception handling.</p><span className="explorer-tech">APIs · CRM · AI workflows</span><ArrowUpRight size={18}/></a></div><a className="explorer-software" href="/services/custom-software"><div className="software-diagram"><span>DATA</span><i/><b>BUSINESS<br/>RULES</b><i/><span>TEAM TOOLS</span></div><div><span className="explorer-label">SYSTEMS &amp; OPERATIONS</span><h3>Custom Software</h3><p>Business systems, dashboards, internal applications and integrations shaped around the way work moves through your organisation.</p><span className="explorer-tech">React · Node.js · Python · PostgreSQL</span></div><ArrowUpRight size={19}/></a></section><section className="connected-solution"><div className="connected-intro"><span className="detail-kicker">HOW WE BRING TECHNOLOGY TOGETHER</span><h2>Connected capabilities<br/>create <em>coherent systems.</em></h2><p>A business outcome may cross several disciplines. A considered solution connects the customer experience to the operations and infrastructure behind it.</p></div><div className="connected-equation">{[['WEBSITE','web'],['eCOMMERCE','commerce'],['AI','ai'],['CLOUD','cloud'],['AUTOMATION','automation']].map(([label,kind],i)=><div className={`equation-node node-${kind}`} key={kind} style={{'--step':i} as React.CSSProperties}><span>{label}</span>{i<4&&<b>+</b>}</div>)}<i className="equation-equals">=</i><div className="equation-result"><Layers3 size={23}/><b>Connected Digital<br/>Business</b></div></div></section><section className="services-process"><div><span className="detail-kicker">FROM CHALLENGE TO DELIVERY</span><h2>Build the right thing,<br/><em>in the right order.</em></h2><p>Clear decisions reduce avoidable rework. Each stage gives the team and stakeholders a useful point to align.</p></div><div className="services-process-steps">{[['Discover','Understand goals, users and current constraints.'],['Plan','Set scope, technical direction and priorities.'],['Design','Shape flows, interface and content structure.'],['Build','Develop in reviewable, useful increments.'],['Test','Validate behaviour, devices and key risks.'],['Launch & scale','Deploy, learn from use and plan improvements.']].map(([title,copy],i)=><article key={title}><span>0{i+1}</span><h3>{title}</h3><p>{copy}</p></article>)}</div></section><section className="services-ecosystem"><div><span className="detail-kicker">A FLEXIBLE TECHNOLOGY ECOSYSTEM</span><h2>Tools chosen<br/>for the job.</h2><p>Technology choices follow functional needs, integration, performance and long-term ownership. The names below reflect tools already present in IAMTECHNI’s project materials.</p></div><div className="ecosystem-orbit"><div>IAMTECHNI<br/><small>TECHNOLOGY</small></div>{['React','Python','OpenAI','Gemini','AWS','Azure','Docker','PostgreSQL','WordPress','WooCommerce','GitHub Actions','Kubernetes'].map((x,i)=><span key={x} style={{'--orbit':i} as React.CSSProperties}>{x}</span>)}</div></section><section className="detail-faq services-faq"><span className="detail-kicker">COMMON QUESTIONS</span><h2>Choosing a starting point.</h2><div className="faq-list">{[['Can several services be part of one project?','Yes. A project can combine capabilities when the business outcome crosses disciplines—for example, a commerce experience connected to inventory, cloud hosting and marketing measurement. Scope should follow the actual requirements.'],['Do I need a technical specification first?','No. Explain the business goal, people involved and current challenge. Discovery can help shape the requirements and identify an appropriate technical approach.'],['How do you choose technologies?','We consider user needs, functionality, integrations, performance, security and who will support the solution over time. A familiar or newer tool is not automatically the right choice.'],['Can IAMTECHNI improve an existing system?','The available services include integration, performance, SEO, cloud and software improvements. A review of the existing system can identify what is practical before deciding to replace it.']].map(([q,a])=><details key={q}><summary>{q}<ChevronDown size={18}/></summary><p>{a}</p></details>)}</div></section><section className="detail-cta"><span className="detail-kicker">A GOOD PLACE TO START</span><h2>Bring the goal.<br/><em>We’ll map the path.</em></h2><p>Tell us what you’re building, improving or trying to make easier. We can help identify the capabilities and next decisions that fit.</p><a className="button button-light" href="/contact">Start a conversation <ArrowUpRight size={16}/></a></section><DetailFooter/></main>}
function PortfolioPage(){return <main className="detail-page detail-portfolio"><DetailHeader/><section className="detail-hero"><span className="detail-eyebrow">PORTFOLIO &amp; WORK</span><h1>Good work starts<br/><em>with a clear purpose.</em></h1><p>Project case studies and verified client outcomes are not available in the current project materials. We won’t present concept visuals as completed client work.</p><a className="button button-primary" href="/contact">Discuss a project <ArrowUpRight size={16}/></a></section><section className="detail-body"><div className="portfolio-editorial"><div className="portfolio-concept-art"><div className="concept-browser"><span>ILLUSTRATIVE CONCEPT</span><b>A clearer<br/>digital storefront.</b><i/><small>PRODUCT · STORY · CHECKOUT</small></div><div className="concept-side">CONCEPT<br/>VISUAL</div></div><div className="portfolio-copy"><span className="detail-kicker">NO CASE STUDIES PUBLISHED</span><h2>We’ll show the work<br/>when the details<br/><em>are ready to share.</em></h2><p>There are no verified project briefs, client permissions or outcome details available in this website project. The visual is an original concept direction for an eCommerce interface, not a deployed project or client engagement.</p><dl><div><dt>Challenge</dt><dd>No client challenge supplied</dd></div><div><dt>Solution</dt><dd>Illustrative direction only</dd></div><div><dt>Technology</dt><dd>To be defined per project</dd></div><div><dt>Outcome</dt><dd>No outcome claims made</dd></div></dl><a className="inline-link" href="/services/ecommerce">Explore eCommerce development <ArrowUpRight size={15}/></a></div></div><section className="detail-faq"><h2>Have a project in mind?</h2><p>We can discuss the business need, constraints and the right first step for your project.</p><a className="button button-primary" href="/contact">Talk with IAMTECHNI <ArrowUpRight size={16}/></a></section></section><DetailFooter/></main>}
function AboutPage(){return <main className="detail-page detail-about"><DetailHeader/><section className="detail-hero"><span className="detail-eyebrow"><Globe2 size={15}/> BUSINESS-FOCUSED TECHNOLOGY</span><h1>Good solutions begin<br />with <em>good questions.</em></h1><p>IAMTECHNI is an independent technology and digital solutions company working with businesses across Pondicherry and Tamil Nadu. We listen first, understand the challenge and bring relevant capabilities together to solve it.</p><div className="detail-hero-actions"><a className="button button-primary" href="/#contact">Meet us through a project <ArrowUpRight size={16}/></a><a className="button-text" href="#who-we-are">Who we are <ArrowRight size={15}/></a></div></section><section className="detail-body"><div className="detail-intro" id="who-we-are"><span>WHO WE ARE</span><h2>Technology should<br />make room for <em>better work.</em></h2><p>Our work spans websites, applications, AI, cloud, software and digital marketing. We focus on matching the solution to the people who will use it and the business outcome it should support. We do not assume every challenge needs a large rebuild or the newest tool.</p></div><div className="detail-split"><div><span className="detail-kicker">WHAT WE DO</span><h2>Capabilities that<br />work together.</h2></div><p>We design and develop digital experiences, connect business systems, improve technology operations and help organisations make practical use of data and automation. A project may need one focused service or a combination of disciplines.</p></div><section className="detail-capabilities"><div className="detail-section-heading"><span className="detail-kicker">OUR APPROACH</span><h2>Understand first.<br /><em>Build with purpose.</em></h2></div><div className="about-pillars">{[['Business context','Start from goals, customers and the process behind the request.'],['Considered technology','Choose tools for suitability, maintainability and integration.'],['Visible collaboration','Keep scope, decisions, feedback and progress clear.'],['Useful after launch','Plan for testing, support and changes as needs develop.']].map(([title,copy],i)=><article key={title}><span>0{i+1}</span><h3>{title}</h3><p>{copy}</p></article>)}</div></section><section className="detail-tech"><div><span className="detail-kicker">TECHNOLOGY PHILOSOPHY</span><h2>Modern where<br />it helps. Simple<br />where it can be.</h2><p>Technology is a means to a business outcome. We consider user needs, delivery constraints, security, integration, performance and who will maintain the result.</p></div><div className="tech-category"><span>AREAS OF EXPERTISE</span>{['Frontend & web','Backend & APIs','AI & machine learning','Cloud & DevOps','Databases & CMS','Marketing & analytics'].map(x=><b key={x}>{x}</b>)}</div></section><section className="detail-use"><div><span className="detail-kicker">INDUSTRIES WE CAN SUPPORT</span><h2>Start from the<br />work, not a label.</h2></div><p>We can explore technology needs across service businesses, retail and eCommerce, professional teams, operations and customer-facing organisations. The right approach depends on the specific audience, process and constraints—not an assumed industry template.</p></section><section className="detail-process"><div className="detail-section-heading"><span className="detail-kicker">HOW WE WORK</span><h2>From first question<br />to what comes next.</h2></div><div className="detail-process-list">{['Discover goals, audience, challenges and requirements.','Plan architecture, scope, priorities and a realistic roadmap.','Design the user experience, visual system and interactions.','Develop with suitable, maintainable technologies.','Test functionality, responsiveness, performance and security.','Launch with production configuration and monitoring in view.','Scale by improving and extending the solution as needs change.'].map((x,i)=><article key={x}><span>0{i+1}</span><p>{x}</p></article>)}</div></section><section className="detail-benefits"><div><span className="detail-kicker">WHY BUSINESSES WORK WITH IAMTECHNI</span><h2>Clear thinking.<br />Connected skills.</h2></div><ul>{['Business goals guide technical decisions.','Custom solutions fit real processes and users.','Modern practices support performance and maintainability.','Integration connects websites, software and existing tools.','AI and cloud capabilities are considered in practical context.','Support can continue as the product and business change.'].map(x=><li key={x}><Check size={17}/>{contentLinks(x)}</li>)}</ul></section><section className="detail-faq"><span className="detail-kicker">QUESTIONS, ANSWERED</span><h2>Getting to know IAMTECHNI.</h2><div className="faq-list">{[['What kind of company is IAMTECHNI?', 'IAMTECHNI is an independent technology and digital solutions company. Its capabilities include web, eCommerce, mobile, AI, custom software, cloud, DevOps, marketing and automation.'],['Where does IAMTECHNI work?', 'The existing company information says IAMTECHNI works with businesses across Pondicherry and Tamil Nadu. Contact the team to discuss a project in your location.'],['Do I need a complete specification before contacting you?', 'No. A clear description of the business challenge, intended users and any known timing is a useful place to begin. Requirements can be explored together.'],['Can services be combined?', 'Yes. For example, a web project may need eCommerce, marketing or cloud support; an AI workflow may connect to custom software and automation. Scope depends on the project.']].map(([q,a])=><details key={q}><summary>{q}<ChevronDown size={18}/></summary><p>{a}</p></details>)}</div></section><section className="detail-cta"><span className="detail-kicker">START A CONVERSATION</span><h2>What are you<br /><em>working through?</em></h2><p>Bring an idea, an operational challenge or a digital product that needs attention. We can help identify what to clarify and which capabilities may fit.</p><a className="button button-light" href="/#contact">Contact IAMTECHNI <ArrowUpRight size={16}/></a><a className="detail-cta-secondary" href="/services">Explore services <ArrowRight size={15}/></a></section></section><DetailFooter/></main>}


function ContactPage(){return <main className="detail-page detail-contact"><DetailHeader/><section className="detail-hero contact-hero"><span className="detail-eyebrow"><MessageCircle size={15}/> START WITH A CONVERSATION</span><h1>Let’s Build Something<br/><em>Remarkable.</em></h1><p>Tell us what you’re building, what problem you’re trying to solve, or what you’d like to improve. A clear first note gives us a useful place to begin.</p></section><section className="contact-two-column"><div className="contact-information"><span className="detail-kicker">WHY CONTACT IAMTECHNI</span><h2>Bring the challenge.<br/>We’ll help frame <em>the next step.</em></h2><p>You do not need a finished specification. Share the context you have and we can identify useful questions, relevant capabilities and a practical way to scope the work.</p><div className="official-contact"><span className="detail-kicker">DIRECT CONTACT</span><a href="mailto:iamtechni.hr@outlook.com"><small>Email</small>iamtechni.hr@outlook.com</a><a href="tel:+917418120053"><small>Phone</small>+91 74181 20053</a></div><h3>Services</h3><div className="contact-service-links">{servicePages.map(page=><a key={page.slug} href={`/services/${page.slug}`}>{labels[page.slug]} <ArrowUpRight size={14}/></a>)}</div><div className="after-enquiry"><b>What happens after an enquiry</b><p>We review the goal and context, clarify requirements, then outline possible scope and next steps.</p></div><div className="location-note"><Globe2 size={16}/><span>Pondicherry, India<br/>Working with businesses across Tamil Nadu</span></div></div><form className="contact-form" onSubmit={event=>{event.preventDefault();const status=event.currentTarget.querySelector('[role=status]');if(status)status.textContent='Your details are ready, but this form is not connected to an enquiry inbox yet.'}}><span className="detail-kicker">PROJECT ENQUIRY</span><h2>Tell us a little more.</h2><div className="form-grid"><label>Name<input name="name" autoComplete="name" required placeholder="Your name"/></label><label>Email<input name="email" type="email" autoComplete="email" required placeholder="you@company.com"/></label><label>Phone<input name="phone" type="tel" autoComplete="tel" placeholder="Optional"/></label><label>Company<input name="company" autoComplete="organization" placeholder="Business or organisation"/></label><label>Service<select name="service" defaultValue=""><option value="" disabled>Select a service</option>{[['AI & Machine Learning','ai-machine-learning'],['Web Development','web-development'],['eCommerce Development','ecommerce'],['Mobile App Development','mobile-app-development'],['Custom Software','custom-software'],['Cloud & DevOps','cloud-devops'],['Digital Marketing','digital-marketing'],['Business Automation','automation'],['Other','other']].map(([name,id])=><option key={id} value={id}>{name}</option>)}</select></label><label>Budget<select name="budget" defaultValue=""><option value="" disabled>Select if known</option><option>Under $5,000</option><option>$5,000–$15,000</option><option>$15,000–$50,000</option><option>$50,000+</option><option>Not sure yet</option></select></label><label className="form-message-field">Message<textarea name="message" rows={5} required placeholder="What are you looking to build or improve?"/></label></div><button className="button button-primary" type="submit">Start the conversation <ArrowUpRight size={16}/></button><p className="form-connection-note" role="status">This form is not connected to an enquiry inbox yet.</p></form></section><section className="detail-body"><section className="detail-faq"><span className="detail-kicker">CONTACT FAQ</span><h2>Before you send a note.</h2><div className="faq-list">{[['Do I need to know which service I need?','No. Describe the outcome or difficulty first. The right technical approach can be discussed after understanding the business context.'],['What should I include in an enquiry?','A short summary of the goal, intended users, current tools and any known timing is useful. Do not include sensitive information in an initial note.'],['Does the form send my enquiry?','No. The form is a front-end interface and is not connected to an enquiry inbox yet. It reports this clearly after submission.'],['Where is IAMTECHNI based?','The project information identifies Pondicherry, India, and says IAMTECHNI works with businesses across Tamil Nadu.']].map(([q,a])=><details key={q}><summary>{q}<ChevronDown size={18}/></summary><p>{a}</p></details>)}</div></section></section><DetailFooter/></main>}
